-- Reference migration for PostgreSQL deployment.
-- The Python models in app/db.py are the executable schema source for local mode.
CREATE TABLE IF NOT EXISTS operator_settings (id SERIAL PRIMARY KEY, timezone VARCHAR(80) NOT NULL DEFAULT 'Europe/Paris', warm_signal_threshold DOUBLE PRECISION NOT NULL DEFAULT 6.0, warm_signal_cron VARCHAR(80) NOT NULL DEFAULT '0 7 * * 1-5', digest_deadline VARCHAR(20) NOT NULL DEFAULT '08:30', linkedin_enabled BOOLEAN NOT NULL DEFAULT FALSE, gmail_send_enabled BOOLEAN NOT NULL DEFAULT FALSE, icp JSONB NOT NULL DEFAULT '{}'::jsonb, offer JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS integration_health (id SERIAL PRIMARY KEY, provider VARCHAR(40) UNIQUE NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'not_configured', last_success_at TIMESTAMPTZ NULL, last_error TEXT NULL, scopes JSONB NOT NULL DEFAULT '[]'::jsonb);
CREATE TABLE IF NOT EXISTS call_events (id SERIAL PRIMARY KEY, event_id VARCHAR(160) UNIQUE NOT NULL, account VARCHAR(160) NOT NULL, ends_at TIMESTAMPTZ NOT NULL, source_status VARCHAR(40) NOT NULL DEFAULT 'pending', attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at TIMESTAMPTZ NULL);
CREATE TABLE IF NOT EXISTS provider_actions (id SERIAL PRIMARY KEY, idempotency_key VARCHAR(200) UNIQUE NOT NULL, provider VARCHAR(40) NOT NULL, action VARCHAR(80) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'proposed', payload JSONB NOT NULL DEFAULT '{}'::jsonb, external_id VARCHAR(200) NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
